import { Injectable, inject } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable } from 'rxjs';

export interface OrderDto {
  id: string;
  status: 'placed' | 'shipped' | 'delivered';
  totalMinor: number; // integer cents/paise, currency specified separately
  currency: string;
}

@Injectable({ providedIn: 'root' })
export class OrdersApi {
  private readonly http = inject(HttpClient);

  list(page: number): Observable<readonly OrderDto[]> {
    if (!Number.isSafeInteger(page) || page < 1) {
      throw new RangeError('page must be a positive integer');
    }
    const params = new HttpParams().set('page', String(page));
    return this.http.get<readonly OrderDto[]>('/api/orders', { params });
  }
}
// The server MUST validate page and enforce per-user order authorization.
// Configuring HttpClient and authentication depends on the Angular version/app.

// Simplified server-side domain validation (framework-independent TypeScript).
interface AppointmentInput {
  clinicianId: string;
  startsAt: string;
}

export function parseAppointment(value: unknown): AppointmentInput {
  if (typeof value !== 'object' || value === null) {
    throw new Error('Request body must be an object');
  }
  const data = value as Record<string, unknown>;
  if (typeof data.clinicianId !== 'string' ||
      !/^[a-zA-Z0-9_-]{1,64}$/.test(data.clinicianId)) {
    throw new Error('Invalid clinicianId');
  }
  if (typeof data.startsAt !== 'string' ||
      !/^\d{4}-\d{2}-\d{2}T/.test(data.startsAt) ||
      !Number.isFinite(Date.parse(data.startsAt))) {
    throw new Error('Invalid startsAt');
  }
  return { clinicianId: data.clinicianId, startsAt: data.startsAt };
}

