import { Component, Injectable, inject, signal } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { finalize } from 'rxjs';

interface ShipmentDto {
  id: string;
  status: 'in_transit' | 'delivered';
  version: number;
}

@Injectable({ providedIn: 'root' })
export class ShipmentApi {
  private readonly http = inject(HttpClient);
  markDelivered(shipment: ShipmentDto) {
    return this.http.patch<ShipmentDto>(
      `/api/shipments/${encodeURIComponent(shipment.id)}/status`,
      { status: 'delivered', expectedVersion: shipment.version }
    );
  }
}

@Component({
  standalone: true,
  selector: 'app-shipment-detail',
  template: `
    @if (shipment(); as s) {
      <p>Shipment {{ s.id }}: {{ s.status }}</p>
      <button type="button" [disabled]="saving() || s.status === 'delivered'"
              (click)="markDelivered()">Mark Delivered</button>
    }
    @if (saving()) { <p role="status">Saving...</p> }
    @if (error()) { <p role="alert">{{ error() }}</p> }
  `
})
export class ShipmentDetailComponent {
  private readonly api = inject(ShipmentApi);
  readonly shipment = signal<ShipmentDto | null>(
    { id: 'demo-123', status: 'in_transit', version: 1 });
  readonly saving = signal(false);
  readonly error = signal<string | null>(null);

  markDelivered(): void {
    const current = this.shipment();
    if (!current || this.saving() || current.status === 'delivered') return;
    this.error.set(null);
    this.saving.set(true);
    this.api.markDelivered(current).pipe(
      finalize(() => this.saving.set(false))
    ).subscribe({
      next: updated => this.shipment.set(updated),
      error: () => this.error.set('Update failed. Refresh and try again.')
    });
  }
}
// Backend MUST authenticate, authorize, validate version/state and commit a
// transaction before returning the updated DTO. UI state is not authoritative.
